// Seed script for Module 3 — Discovery & Market.
// Inserts 3 ventures (bebus, ecocomp, real) + realistic evidence, scored via the
// shared engine, with auto-generated market risks. Run: npx tsx seed-discovery.mjs
import { drizzle } from "drizzle-orm/node-postgres";
import pg from "pg";
import { eq, and } from "drizzle-orm";
import {
  ventures, customerSegments, problemHypotheses, customerInterviews,
  dmCompetitors, demandSignals, wtpTests, marketRisks,
} from "./drizzle/schema.ts";
import {
  calculateCustomerDiscoveryScore, calculateCompetitiveRiskScore,
  calculateDemandSignalScore, calculateWTPScore, calculateMarketRiskScore,
  generateLeanDecision, autoRisksForInterview, autoRisksForCompetitor,
  autoRisksForDemandSignal, autoRisksForWTP,
} from "./shared/discoveryMarket.ts";

const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });
const db = drizzle(pool);

const VENTURES = [
  { id: "bebus", name: "BEBUS", tagline: "Demand-responsive rural transport", sector: "Mobility", color: "#3B85BA" },
  { id: "ecocomp", name: "ECOCOMP", tagline: "Bio-based composite materials", sector: "Advanced Materials", color: "#56A837" },
  { id: "real", name: "REAL", tagline: "Real-time emissions accounting", sector: "Climate Tech", color: "#F69111" },
];

async function clearVenture(vid) {
  for (const t of [marketRisks, customerInterviews, dmCompetitors, demandSignals, wtpTests, problemHypotheses, customerSegments]) {
    await db.delete(t).where(eq(t.ventureId, vid));
  }
}

async function syncAutoRisks(ventureId, linkedModule, linkedRecordId, specs) {
  for (const spec of specs) {
    await db.insert(marketRisks).values({
      ventureId, linkedModule, linkedRecordId,
      riskTitle: spec.riskTitle, riskCategory: spec.riskCategory,
      riskDescription: `Auto-generated from ${linkedModule}.`,
      probabilityScore: spec.probabilityScore, severityScore: spec.severityScore,
      evidenceConfidenceScore: spec.evidenceConfidenceScore,
      marketRiskScore: calculateMarketRiskScore(spec),
      requiredExperiment: spec.requiredExperiment, status: "open", autoGenerated: true,
    });
  }
}

