async function seedVenture(vid) {
  const cfg = DATA[vid];
  await clearVenture(vid);

  const [seg] = await db.insert(customerSegments).values({ ventureId: vid, ...cfg.segment }).returning();
  const [hyp] = await db.insert(problemHypotheses).values({ ventureId: vid, customerSegmentId: seg.id, ...cfg.hypothesis }).returning();

  for (const it of cfg.interviews) {
    const score = calculateCustomerDiscoveryScore(it);
    const [row] = await db.insert(customerInterviews).values({
      ventureId: vid, customerSegmentId: seg.id, problemHypothesisId: hyp.id, ...it,
      discoveryScore: score, recommendedDecision: generateLeanDecision("customer_discovery", score).join("; "),
    }).returning();
    await syncAutoRisks(vid, "customer_discovery", row.id, autoRisksForInterview(it));
  }

  for (const c of cfg.competitors) {
    const crs = calculateCompetitiveRiskScore(c);
    const [row] = await db.insert(dmCompetitors).values({ ventureId: vid, problemHypothesisId: hyp.id, ...c, competitiveRiskScore: crs }).returning();
    await syncAutoRisks(vid, "competitor", row.id, autoRisksForCompetitor({ ...c, competitiveRiskScore: crs }));
  }

  for (const d of cfg.signals) {
    const dss = calculateDemandSignalScore(d);
    const [row] = await db.insert(demandSignals).values({ ventureId: vid, problemHypothesisId: hyp.id, ...d, demandSignalScore: dss }).returning();
    await syncAutoRisks(vid, "demand", row.id, autoRisksForDemandSignal(d));
  }

  for (const w of cfg.wtp) {
    const ws = calculateWTPScore(w);
    const [row] = await db.insert(wtpTests).values({ ventureId: vid, problemHypothesisId: hyp.id, ...w, wtpScore: ws }).returning();
    await syncAutoRisks(vid, "wtp", row.id, autoRisksForWTP(w));
  }

  console.log(`  ✓ seeded ${vid}`);
}

async function main() {
  for (const v of VENTURES) {
    await db.insert(ventures).values({ ...v, status: "Pre-Launch", vrl: 2, trl: 3 }).onConflictDoNothing();
  }
  console.log("Ventures ensured.");
  for (const v of VENTURES) await seedVenture(v.id);
  console.log("Done.");
  await pool.end();
}

main().catch((e) => { console.error(e); process.exit(1); });
